const output = $json.output || '';

const isValidOutputLength 
  = output.length < $json.maxTokensCount

if (!isValidOutputLength) {
  return [
    {
      json: {
        output: 'Your message is too long for processing. Please shorten it or split it into smaller parts and try again.',
        length: output.length,
        isValidOutputLength: isValidOutputLength
      }
    }
  ];
}

return [
  {
    json: {
      output: output,
      length: output.length,
      isValidOutputLength: isValidOutputLength
    }
  }
];

const cleaned = $input.first().json.content
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

const parsed = JSON.parse(cleaned);
parsed.output = $('Moderation Output Length').first().json.output;
return [
  {
    json: parsed
  }
];

let output = $input.first().json.output;
const categories = $input.first().json.categories;
const category_scores = $input.first().json.category_scores;
const isValidOutputLength = $('Moderation Output Length').first().json.isValidOutputLength
const flagged = $input.first().json.flagged

if (flagged) {
  output = 'Sorry, I cannot process this request.';
}

return [
  {
    json: {
      output: output,
      categories: categories,
      category_scores: category_scores,
      flagged: flagged,
      isValidOutputLength: isValidOutputLength
    }
  }
];
